import argparse
import sys
import os
import json
from tqdm import tqdm
import numpy as np
sys.path.append(os.path.dirname(os.path.abspath(__file__)))

from metrics.fc import FactualConsistency
from metrics.intra_nli import IntraNLI
from metrics.mhic import MHIC


class AffinitiTherapySessionSummaryEvaluationBundle:
    def __init__(self):
        self.intra_nli = IntraNLI(hf_cache_dir=None)
        self.mhic = MHIC()
        self.fc_document = FactualConsistency()

    def evaluate(self, llm_summaries: dict, gold_summaries: dict, posts: dict = None) -> dict:
        results = {
            'intra_nli': {"document_level": [], "mean": None},
            'mhic': {"document_level": [], "mean": None},
            'fc_document': {"document_level": [], "mean": None, "detail": []},
            'document_ids': list(llm_summaries.keys())
        }

        for document_id in tqdm(results['document_ids']):
            llm_summary = llm_summaries[document_id]
            gold_summary = gold_summaries[document_id]
            document_posts = posts[document_id]

            intra_nli_score = self.intra_nli.calculate_metric(llm_summary)
            results['intra_nli']['document_level'].append(intra_nli_score)

            mhic_score = self.mhic.calculate_metric(llm_summary, document_posts)
            results['mhic']['document_level'].append(mhic_score)

            fc_document_score, fc_document_detail = self.fc_document.calculate_metric(llm_summary, document_posts)
            results['fc_document']['document_level'].append(fc_document_score)
            results['fc_document']['detail'].append(fc_document_detail)

        for metric_id in ['intra_nli', 'mhic', 'fc_document']:
            results[metric_id]['mean'] = float(np.mean(results[metric_id]['document_level']))

        return results


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Evaluate affiniti_therapy_session_summary.")
    parser.add_argument('--llm_summaries', type=str, help='Path to the LLM summaries JSON file.')
    parser.add_argument('--gold_summaries', type=str, help='Path to the gold summaries JSON file.')
    parser.add_argument('--combined_summaries', type=str, default=None, help='Path to the combined summaries JSON file (optional). If provided, it will be used instead of LLM summaries and gold summaries.')
    parser.add_argument('--posts', type=str, required=True, help='Path to the posts JSON file (document_id -> list of source texts).')
    parser.add_argument('--output_file', type=str, default='affiniti_therapy_session_summary_evaluation_results.json', help='Path to save the evaluation results JSON file.')
    args = parser.parse_args()

    if args.combined_summaries:
        print(f"Loading combined summaries from {args.combined_summaries}")
        with open(args.combined_summaries, 'r') as f:
            combined_summaries = json.load(f)
        llm_summaries = {key: value["summary"] for key, value in combined_summaries.items()}
        gold_summaries = {key: value["reference"] for key, value in combined_summaries.items()}
    elif args.llm_summaries and args.gold_summaries:
        print(f"Loading LLM summaries from {args.llm_summaries}")
        with open(args.llm_summaries, 'r') as f:
            llm_summaries = json.load(f)
        print(f"Loading gold summaries from {args.gold_summaries}")
        with open(args.gold_summaries, 'r') as f:
            gold_summaries = json.load(f)
    else:
        raise ValueError("Either --combined_summaries or both --llm_summaries and --gold_summaries must be provided.")

    print(f"Loading posts from {args.posts}")
    with open(args.posts, 'r') as f:
        posts = json.load(f)

    print("Creating evaluation bundle for affiniti_therapy_session_summary.")
    evaluation_bundle = AffinitiTherapySessionSummaryEvaluationBundle()
    print("Evaluating LLM.")
    results = evaluation_bundle.evaluate(llm_summaries, gold_summaries, posts)

    print(f"Saving evaluation results to {args.output_file}")
    output_file = args.output_file
